class Solution:
    def lastSubstring(self, s: str) -> str:
        n = len(s)
        best = 0
        for i in range(1, n):
            j = 0
            while i + j < n and s[best + j] == s[i + j]:
                j += 1
            if i + j < n and s[i + j] > s[best + j]:
                best = i
        return s[best:]

